(function(){"use strict";window.D_STUDY_TU101_LECTURES=window.D_STUDY_TU101_LECTURES||{};window.D_STUDY_TU101_LECTURES["l3"]={"id":"l3","lectureNumber":3,"lectureLabel":"Lecture 3","title":"ASEAN Between Giants: U.S., China, and the New Global Cold War","theme":"Theme 1 — Understanding the Contemporary World","bankVersion":"tu101-l3-v13.16","source":"Professor Pongphisoot ASEAN Between Giants slide (primary) + Kuik hedging reading (support) + user handwritten L4 summary (uploaded notebook supplement)","summary":[{"id":"tu3s1","titleEn":"1. Post-Cold War East Asia — Opportunity + Uncertainty","titleTh":"1. เอเชียตะวันออกหลังสงครามเย็น — โอกาส + ความไม่แน่นอน","memoryEn":"MEMORY HOOK: US stays, China rises, old tensions survive.","memoryTh":"จำ: สหรัฐฯ ยังอยู่ • จีนขึ้นมา • ความตึงเครียดเก่ายังไม่หาย","bullets":[{"en":"The U.S. remained a major <b>security guarantor</b>, but its regional attention has moved between retreat and engagement.","th":"สหรัฐฯ ยังเป็น <b>security guarantor</b> สำคัญ แต่ระดับการมีส่วนร่วมขึ้นลง"},{"en":"China emerged as a rising power while some Cold War tensions remained, especially the Korean Peninsula and Taiwan.","th":"จีนเติบโตเป็นมหาอำนาจ ขณะที่ความตึงเครียดอย่างคาบสมุทรเกาหลีและไต้หวันยังอยู่"},{"en":"Economic globalization and regional institutions expanded, but East Asian mechanisms remained mostly <b>state-centric</b>, unlike the EU.","th":"เศรษฐกิจโลกาภิวัตน์และสถาบันภูมิภาคขยายตัว แต่กลไกเอเชียตะวันออกยังค่อนข้าง <b>state-centric</b>"},{"en":"Democratization occurred in some places while authoritarian and socialist systems remained in others.","th":"บางประเทศประชาธิปไตยมากขึ้น ขณะที่บางประเทศยังเป็นเผด็จการหรือสังคมนิยม"}],"understandEn":"The post-Cold War era did not create a simple peaceful order. It mixed U.S. security presence, China’s rise, economic integration, unresolved conflicts and diverse regimes.","understandTh":"หลังสงครามเย็นไม่ได้สงบแบบง่าย ๆ แต่เป็นส่วนผสมของบทบาทสหรัฐฯ การขึ้นของจีน เศรษฐกิจเชื่อมกัน ความขัดแย้งค้าง และระบอบการเมืองหลากหลาย","diagram":["U.S. presence","China rises","Regional institutions","Strategic uncertainty"]},{"id":"tu3s2","titleEn":"2. China’s Rise & U.S. Responses","titleTh":"2. การขึ้นของจีนและการตอบสนองของสหรัฐฯ","memoryEn":"MEMORY HOOK: Wealth → technology → military → influence.","memoryTh":"จำ: เศรษฐกิจ → เทคโนโลยี → ทหาร → อิทธิพล","bullets":[{"en":"China’s rise includes economic growth, poverty reduction and higher living standards, but also <b>technological upgrading, military modernization and proactive diplomacy</b>.","th":"การขึ้นของจีนไม่ใช่แค่เศรษฐกิจ แต่รวม <b>เทคโนโลยี การทหาร และการทูตเชิงรุก</b>"},{"en":"U.S. strategy continues to use a <b>hub-and-spoke alliance system</b> plus newer strategic partnerships.","th":"สหรัฐฯ ใช้ระบบพันธมิตรแบบ <b>hub-and-spoke</b> พร้อม strategic partnerships ใหม่"},{"en":"Obama’s <b>Pivot to Asia</b> reprioritized Asia-Pacific, reassured allies and expanded economic/political engagement.","th":"Obama ใช้ <b>Pivot to Asia</b> เพื่อให้น้ำหนักเอเชียมากขึ้นและยืนยันพันธมิตร"},{"en":"Trump emphasized <b>America First</b> and the <b>Free and Open Indo-Pacific</b>, with a more transactional and competitive approach to China.","th":"Trump เน้น <b>America First</b> และ <b>FOIP</b> ด้วยแนวทางแข่งขันกับจีนมากขึ้น"},{"en":"Biden retained China as a strategic competitor while restoring emphasis on alliances, multilateralism and liberal norms.","th":"Biden ยังมองจีนเป็น strategic competitor แต่กลับมาเน้นพันธมิตร multilateralism และ liberal norms"},{"en":"<b>Obama:</b> the notebook adds Pivot to Asia plus joining the EAS / TAC around 2009–10.","th":"<b>Obama:</b> โน้ตเพิ่ม Pivot to Asia และการเข้าร่วม EAS / TAC ราว 2009–10"},{"en":"<b>Trump:</b> “America First” + “Free and Open Indo-Pacific,” with the notebook explicitly connecting this to limiting / decoupling China.","th":"<b>Trump:</b> “America First” + “Free and Open Indo-Pacific” และโน้ตเชื่อมกับ limiting / decoupling China"},{"en":"<b>Biden:</b> competition with China continues, but the notebook adds a return to liberal multilateralism plus <b>QUAD, IPEF, AUKUS and Mekong–U.S. Partnership</b>.","th":"<b>Biden:</b> ยังแข่งขันกับจีน แต่โน้ตเพิ่ม liberal multilateralism + <b>QUAD, IPEF, AUKUS, Mekong–U.S. Partnership</b>"}],"understandEn":"The administrations differ in style, but the lecture emphasizes continuity: managing China’s rise remains a central U.S. strategic problem.","understandTh":"รัฐบาลสหรัฐฯ แต่ละยุคต่างสไตล์ แต่มีความต่อเนื่องสำคัญคือการรับมือการขึ้นของจีน","diagram":["Obama Pivot","Trump FOIP","Biden alliances","China competition"]},{"id":"tu3s3","titleEn":"3. China’s New Foreign-Policy Toolkit","titleTh":"3. เครื่องมือนโยบายต่างประเทศใหม่ของจีน","memoryEn":"MEMORY HOOK: Struggle + GDI + GSI + GCI.","memoryTh":"จำ: กล้าสู้ + GDI + GSI + GCI","bullets":[{"en":"Xi-era rhetoric presents China as a major power and emphasizes <b>major-country diplomacy with Chinese characteristics</b>.","th":"ยุค Xi จีนย้ำสถานะมหาอำนาจและ <b>major-country diplomacy with Chinese characteristics</b>"},{"en":"The lecture notes a tougher tone: <b>“dare to struggle”</b> and so-called Wolf Warrior diplomacy.","th":"สไลด์กล่าวถึงท่าทีแข็งขึ้น เช่น <b>dare to struggle</b> และ Wolf Warrior diplomacy"},{"en":"<b>GDI</b> focuses on development and SDGs; <b>GSI</b> promotes a Chinese security vision; <b>GCI</b> emphasizes civilization, dialogue and inclusiveness.","th":"<b>GDI</b> เน้นการพัฒนา, <b>GSI</b> เน้นความมั่นคง, <b>GCI</b> เน้นอารยธรรม/การสนทนา"}],"understandEn":"China does not only react militarily. It also competes by offering development, security and normative initiatives that seek influence in global governance.","understandTh":"จีนไม่ได้แข่งขันแค่ทหาร แต่เสนอกรอบการพัฒนา ความมั่นคง และแนวคิดเชิงบรรทัดฐานเพื่อเพิ่มอิทธิพล","diagram":["GDI","GSI","GCI","Influence"]},{"id":"tu3s4","titleEn":"4. Why Southeast Asia Does Not Want a Binary Choice","titleTh":"4. ทำไมเอเชียตะวันออกเฉียงใต้ไม่อยากเลือกข้างแบบสองขั้ว","memoryEn":"MEMORY HOOK: Avoid domination, abandonment and disorder.","memoryTh":"จำ: ไม่อยากถูกจีนครอบงำ • ไม่อยากให้สหรัฐฯ ถอน • ไม่อยากให้ภูมิภาควุ่นวาย","bullets":[{"en":"The lecture summarizes three concerns: <b>China’s domination, U.S. withdrawal, and an unstable regional order</b>.","th":"3 ความกังวลคือ <b>จีนครอบงำ สหรัฐฯ ถอนตัว และระเบียบภูมิภาคไม่มั่นคง</b>"},{"en":"Southeast Asian states value China’s economic opportunities but also value U.S. security presence and other external partners.","th":"รัฐในภูมิภาคต้องการผลประโยชน์เศรษฐกิจกับจีน แต่ก็ต้องการบทบาทความมั่นคงของสหรัฐฯ และคู่ค้าอื่น"},{"en":"Because benefits and risks differ across issues, a simple pro-U.S./pro-China label often misses actual policy behavior.","th":"เพราะแต่ละประเด็นมีผลดี/ความเสี่ยงต่างกัน ป้าย pro-US/pro-China จึงมักอธิบายไม่พอ"}],"understandEn":"The region’s strategy is driven by uncertainty. States want room to maneuver and do not want any single great power to become indispensable or dominant.","understandTh":"กลยุทธ์เกิดจากความไม่แน่นอน รัฐต้องการพื้นที่ขยับและไม่อยากพึ่งมหาอำนาจใดจนขาดทางเลือก","diagram":["China benefit","China risk","U.S. security","Keep options"]},{"id":"tu3s5","titleEn":"5. Hedging — Insurance Under Uncertainty","titleTh":"5. Hedging — การทำประกันเชิงยุทธศาสตร์ภายใต้ความไม่แน่นอน","memoryEn":"MEMORY HOOK: Don’t choose one side; combine counteracting moves.","memoryTh":"จำ: ไม่เลือกข้างเต็มตัว • ใช้มาตรการตรงข้ามกันเพื่อกันความเสี่ยง","bullets":[{"en":"<b>Hedging</b> is an insurance strategy that reduces risk and preserves options when future intentions and outcomes are uncertain.","th":"<b>Hedging</b> คือกลยุทธ์ประกันความเสี่ยงและรักษาทางเลือกเมื่ออนาคตไม่แน่นอน"},{"en":"Three elements in the slide: <b>not taking sides</b>, using <b>opposite/counteracting measures</b>, and preserving gains plus a <b>fallback position</b>.","th":"3 องค์ประกอบ: <b>ไม่เลือกข้าง</b> ใช้มาตรการที่ <b>ถ่วงกัน</b> และรักษาผลประโยชน์พร้อม <b>fallback</b>"},{"en":"Kuik’s reading helps frame hedging as <b>risk management</b>, not simple neutrality or indecision.","th":"บทอ่าน Kuik ช่วยให้มอง hedging เป็น <b>risk management</b> ไม่ใช่ความเป็นกลางหรือโลเล"}],"understandEn":"A state can economically engage China while improving military ties with the U.S. This apparent contradiction is exactly what makes hedging a risk-management portfolio.","understandTh":"รัฐอาจค้ากับจีนมากขึ้นพร้อมเสริมความร่วมมือทหารกับสหรัฐฯ ความดูเหมือนขัดกันนี้คือแก่นของ hedging","diagram":["Engage","Balance","Diversify","Fallback"]},{"id":"tu3s6","titleEn":"6. Five Hedging Behaviors","titleTh":"6. พฤติกรรม Hedging 5 แบบ","memoryEn":"MEMORY HOOK: Pragmatism • soft balance • deny dominance • bind • limited bandwagon.","memoryTh":"จำ: ผลประโยชน์เศรษฐกิจ • ถ่วงอ่อน • กันการครอบงำ • ผูกไว้ในสถาบัน • ร่วมบางเรื่อง","bullets":[{"en":"<b>Economic pragmatism:</b> maximize economic benefits through cooperation and links.","th":"<b>Economic pragmatism:</b> เพิ่มผลประโยชน์เศรษฐกิจผ่านความร่วมมือ"},{"en":"<b>Indirect/soft balancing:</b> strengthen defense alignment or capabilities without explicitly targeting a power.","th":"<b>Indirect/soft balancing:</b> เสริมกำลัง/ความร่วมมือความมั่นคงโดยไม่ประกาศชี้เป้า"},{"en":"<b>Dominance denial:</b> cultivate political ties with multiple actors to avoid subservience.","th":"<b>Dominance denial:</b> กระจายสายสัมพันธ์เพื่อไม่ให้ถูกมหาอำนาจเดียวครอบงำ"},{"en":"<b>Binding engagement:</b> enmesh external powers in ASEAN-led bilateral and multilateral processes.","th":"<b>Binding engagement:</b> ดึงมหาอำนาจเข้าอยู่ในเครือข่ายความร่วมมือที่ ASEAN นำ"},{"en":"<b>Limited bandwagoning:</b> selectively collaborate with one power without becoming its security client.","th":"<b>Limited bandwagoning:</b> ร่วมมือกับมหาอำนาจบางเรื่องแต่ไม่ผูกตัวเป็นลูกค้าความมั่นคง"}],"understandEn":"These are not mutually exclusive boxes. A hedging portfolio can contain several at once, depending on issue and risk.","understandTh":"พฤติกรรมเหล่านี้เกิดพร้อมกันได้ เพราะ hedging เป็นพอร์ตหลายเครื่องมือที่ปรับตามประเด็นและความเสี่ยง","diagram":["Economic pragmatism","Soft balance","Dominance denial","Binding / limited alignment"]},{"id":"tu3s7","titleEn":"7. ASEAN Centrality — Strengths and Limits","titleTh":"7. ASEAN Centrality — จุดแข็งและข้อจำกัด","memoryEn":"MEMORY HOOK: Convene, socialize, constrain — but cannot enforce strongly.","memoryTh":"จำ: เรียกทุกฝ่ายเข้าหากัน • สร้างบรรทัดฐาน • ลดแรงปะทะ แต่บังคับใช้ไม่แข็ง","bullets":[{"en":"ASEAN can help fill a regional power vacuum and create a <b>thickening effect</b> through thousands of meetings, forums and networks.","th":"ASEAN ช่วยเติมช่องว่างอำนาจและสร้าง <b>thickening effect</b> ผ่านการประชุม/เครือข่ายจำนวนมาก"},{"en":"The <b>ASEAN Way</b> emphasizes non-interference, informality, consultation, consensus and peaceful dispute settlement; the TAC embodies core norms.","th":"<b>ASEAN Way</b> เน้นไม่แทรกแซง ความไม่เป็นทางการ การปรึกษา ฉันทามติ และแก้ข้อพิพาทโดยสันติ; TAC เป็นหลักสำคัญ"},{"en":"As middle/small states, ASEAN members are less threatening to great powers and can provide an acceptable institutional platform.","th":"สมาชิก ASEAN เป็นรัฐขนาดกลาง/เล็ก จึงเป็นเวทีที่มหาอำนาจยอมรับได้มากกว่า"},{"en":"But non-interference, weak enforcement, internal divisions and state-centric approaches limit responses to human-rights crises and great-power bargaining.","th":"แต่ non-interference การบังคับใช้ต่ำ ความแตกต่างภายใน และ state-centric จำกัดประสิทธิภาพ โดยเฉพาะวิกฤตสิทธิ/การต่อรองมหาอำนาจ"}],"understandEn":"ASEAN centrality is mainly institutional and convening power. It can shape habits and architecture, but it does not mean ASEAN can command great powers or always enforce agreements.","understandTh":"ASEAN centrality คืออำนาจด้านสถาบันและการเป็นเวทีกลาง ไม่ได้แปลว่า ASEAN สั่งมหาอำนาจหรือบังคับข้อตกลงได้เสมอ","diagram":["Meetings","ASEAN Way / TAC","Central platform","Weak enforcement"]},{"id":"tu3s8","titleEn":"8. Why Southeast Asia Matters — Geography, Power Vacuum & Strategic Choice","titleTh":"8. Why Southeast Asia Matters — ภูมิศาสตร์ ช่องว่างอำนาจ และการเลือกเชิงยุทธศาสตร์","memoryEn":"MEMORY HOOK: chokepoints + power vacuum + two giants = strong incentive to hedge.","memoryTh":"จำ: chokepoints + power vacuum + มหาอำนาจ 2 ฝ่าย = แรงจูงใจให้ hedge","bullets":[{"en":"The notebook highlights Southeast Asia’s <b>maritime oil-transit chokepoints</b> as a reason the region matters strategically between the U.S. and China.","th":"โน้ตเน้น <b>maritime oil-transit chokepoints</b> ว่าเป็นเหตุผลที่ภูมิภาคสำคัญเชิงยุทธศาสตร์ระหว่าง U.S. กับ China"},{"en":"The post-Cold War note keeps three background conditions: <b>old conflicts remain</b> (North–South Korea; China–Taiwan), <b>not all Asia democratized</b>, and a possible <b>power vacuum</b> if U.S. engagement falls.","th":"โน้ตหลัง Cold War เก็บ 3 เงื่อนไข: <b>old conflicts remain</b>, <b>not all Asia democratized</b>, และ <b>power vacuum</b> ถ้า U.S. engagement ลดลง"},{"en":"That combination makes a binary choice costly: Southeast Asian states want room to benefit from both powers while avoiding domination, abandonment or entrapment.","th":"เงื่อนไขนี้ทำให้การเลือกข้างแบบ binary มีต้นทุนสูง รัฐในภูมิภาคจึงต้องการได้ประโยชน์จากทั้งสองฝ่ายและเลี่ยง domination / abandonment / entrapment"},{"en":"The page places <b>hedging</b> between balancing and bandwagoning — an insurance-like strategy that tries to save relationships on both sides.","th":"หน้าโน้ตวาง <b>hedging</b> ไว้ระหว่าง balancing กับ bandwagoning เป็นกลยุทธ์คล้าย insurance ที่พยายามรักษาความสัมพันธ์ทั้งสองด้าน"}],"understandEn":"The geographic and political setting explains why hedging is not indecision. Southeast Asia sits on strategic maritime routes while facing uncertainty about U.S. commitment and China’s rise, so keeping options open becomes a deliberate strategy.","understandTh":"ภูมิศาสตร์และการเมืองช่วยอธิบายว่า hedging ไม่ใช่ลังเล: ภูมิภาคอยู่บนเส้นทางทะเลยุทธศาสตร์ พร้อมความไม่แน่นอนเรื่อง U.S. commitment และ China’s rise จึงต้องรักษาทางเลือก","diagram":["Maritime chokepoints","U.S. engagement uncertainty","China rises","Power vacuum risk","Hedging"]},{"id":"tu3s9","titleEn":"9. Kuik Reading — Riskification & Dynamic Hedging","titleTh":"9. Kuik Reading — Riskification และ Dynamic Hedging","memoryEn":"MEMORY HOOK: shades of gray; identify risk, diversify, stay flexible.","memoryTh":"จำ: shades of gray → identify risk → diversify → flexible","bullets":[{"en":"The notebook summarizes ASEAN as <b>“shades of gray — no black & white.”</b>","th":"โน้ตสรุป ASEAN ว่า <b>“shades of gray — no black & white”</b>"},{"en":"Four risks are listed: <b>entrapment, abandonment, polarization, marginalization</b>.","th":"ความเสี่ยง 4 อย่างในโน้ต: <b>entrapment, abandonment, polarization, marginalization</b>"},{"en":"<b>Riskification:</b> identify a risk → prioritize it → downplay other risks. The page says this depends on <b>structural conditions</b> (who is powerful) and <b>domestic elite politics</b>.","th":"<b>Riskification:</b> identify risk → prioritize → downplay other risk และขึ้นกับ <b>structural conditions</b> + <b>domestic elite politics</b>"},{"en":"Three hedging characteristics are written explicitly: <b>inclusive diversification</b>, <b>active impartiality</b>, and <b>prudent contradictions</b> — using relationships that can counteract one another and preserve a fallback position.","th":"คุณลักษณะ 3 อย่าง: <b>inclusive diversification</b>, <b>active impartiality</b>, <b>prudent contradictions</b> เพื่อรักษา fallback position"},{"en":"The notebook contrasts <b>risk</b> with a more certain <b>threat</b>, and ends with the key point: <b>hedging is dynamic, not fixed</b>.","th":"โน้ตเทียบ <b>risk</b> กับ <b>threat</b> ที่แน่นอนกว่า และจบด้วย <b>hedging is dynamic, not fixed</b>"}],"understandEn":"Kuik’s framework makes hedging a process, not a label. States continuously reassess which risks matter most, which partner is becoming more powerful, and what domestic elites prefer; the portfolio therefore changes over time.","understandTh":"กรอบ Kuik ทำให้ hedging เป็น process ไม่ใช่ป้ายตายตัว: รัฐประเมิน risk, power และ domestic elite politics ใหม่เรื่อย ๆ จึงเปลี่ยนพอร์ตความสัมพันธ์ตามเวลา","diagram":["Entrapment / abandonment","Riskification","Diversify","Active impartiality","Dynamic hedging"]}],"parts":{"tu3-order":{"label":"Part 1 • Post-Cold War Order & Great-Power Competition","source":"Professor Pongphisoot ASEAN Between Giants slide (primary) + Kuik hedging reading (support)","summaries":["tu3s1","tu3s2","tu3s3"],"topics":["ASEAN between the United States and China"]},"tu3-hedging":{"label":"Part 2 • Strategic Uncertainty & Hedging","source":"Professor Pongphisoot ASEAN Between Giants slide (primary) + Kuik hedging reading (support)","summaries":["tu3s4","tu3s5","tu3s8","tu3s9"],"topics":["Why Southeast Asian states avoid binary alignment","Strategic uncertainty, riskification, and hedging"]},"tu3-tools":{"label":"Part 3 • Hedging Tools & ASEAN Centrality","source":"Professor Pongphisoot ASEAN Between Giants slide (primary) + Kuik hedging reading (support)","summaries":["tu3s6","tu3s7"],"topics":["Strategic uncertainty, riskification, and hedging","Why Southeast Asian states avoid binary alignment"]},"tu3-limits":{"label":"Part 4 • ASEAN Limits & Regional Order","source":"Professor Pongphisoot ASEAN Between Giants slide (primary) + Kuik hedging reading (support)","summaries":["tu3s7"],"topics":["Why Southeast Asian states avoid binary alignment"]},"tu3-all":{"label":"Cumulative • Lecture 3","source":"Professor Pongphisoot ASEAN Between Giants slide (primary) + Kuik hedging reading (support)","summaries":["tu3s1","tu3s2","tu3s3","tu3s4","tu3s5","tu3s6","tu3s7"],"topics":null,"cumulative":true}},"review":{"tu3-order":[{"q":"What role did the U.S. retain in post-Cold War East Asia?","opts":["A major security guarantor whose engagement still fluctuated","A power that completely left Asia","Only an economic actor with no security role","A subordinate member of ASEAN"],"ans":0,"topic":"ASEAN between the United States and China","why":"The slide says the U.S. remained a major great power/security guarantor but vacillated between retreat and engagement."},{"q":"What does the lecture include in the 'rise of China' beyond GDP growth?","opts":["Technological upgrading, military modernization and proactive foreign policy","Only population growth","Withdrawal from international politics","A decline in living standards"],"ans":0,"topic":"ASEAN between the United States and China","why":"The slide treats China’s rise as economic, technological, military and diplomatic."},{"q":"Which unresolved tensions remain from the Cold War environment?","opts":["The Korean Peninsula and Taiwan issue","The Napoleonic Wars and Crimea only","The dissolution of ASEAN","The end of all territorial disputes"],"ans":0,"topic":"ASEAN between the United States and China","why":"The lecture explicitly lists Korea and Taiwan as persistent tensions."},{"q":"Which institutions illustrate expanding East Asian regionalism?","opts":["ASEAN, APEC, AFTA, ARF, ASEAN+3 and East Asia Summit","EU institutions only","NATO and Warsaw Pact only","No regional institutions existed"],"ans":0,"topic":"ASEAN between the United States and China","why":"The slide lists these as examples of proliferating regional institutions."},{"q":"What concern followed reduced U.S. presence after the Vietnam War?","opts":["A perceived power vacuum and uncertainty about Japan and China","Automatic ASEAN military unity","The end of Japanese influence","No concern about regional leadership"],"ans":0,"topic":"ASEAN between the United States and China","why":"The slide links reduced U.S. presence to concerns over who would shape regional order."},{"q":"What is the hub-and-spoke system?","opts":["U.S.-centered bilateral alliances linking Washington separately with regional allies","ASEAN’s consensus voting procedure","China’s Belt and Road financing network only","A global free-trade tariff schedule"],"ans":0,"topic":"ASEAN between the United States and China","why":"The lecture identifies hub-and-spoke alliances as a continuing U.S. security structure."},{"q":"What was a core purpose of Obama’s Pivot to Asia?","opts":["Reprioritize Asia-Pacific, manage China’s rise and reassure allies","Withdraw from all Asian forums","Replace ASEAN with NATO","End economic engagement in Asia"],"ans":0,"topic":"ASEAN between the United States and China","why":"The Pivot sought to reflect the shift of global gravity toward Asia."},{"q":"What distinguished Trump’s Asia approach in the lecture?","opts":["America First, transactional diplomacy and promotion of the Free and Open Indo-Pacific","Return to the Warsaw Pact","Abandonment of competition with China","Abolition of bilateral bargaining"],"ans":0,"topic":"ASEAN between the United States and China","why":"The slide links FOIP to competition with China and BRI."},{"q":"What is a major continuity under Biden?","opts":["China remains a strategic competitor","China becomes a formal U.S. ally","The U.S. exits the Indo-Pacific","All alliances are abandoned"],"ans":0,"topic":"ASEAN between the United States and China","why":"The slide emphasizes continuity on China despite changes in style."},{"q":"Which trio represents China’s newer global initiatives?","opts":["GDI, GSI and GCI","TPP, QUAD and AUKUS","APEC, AFTA and ARF","NATO, EU and OECD"],"ans":0,"topic":"ASEAN between the United States and China","why":"The lecture identifies Global Development, Security and Civilization Initiatives."}],"tu3-hedging":[{"q":"Which three outcomes does Southeast Asia seek to prevent in the slide?","opts":["China’s domination, U.S. withdrawal and unstable regional order","Chinese withdrawal, U.S. domination and ASEAN expansion","Economic growth, regionalism and democracy","Trade, tourism and migration"],"ans":0,"topic":"Why Southeast Asian states avoid binary alignment","why":"These are the three policy concerns explicitly summarized by the professor."},{"q":"What is hedging in this lecture?","opts":["Risk-management behavior that preserves options under strategic uncertainty","Permanent neutrality with no external relations","Full military alignment with the strongest state","A purely economic tariff policy"],"ans":0,"topic":"Strategic uncertainty, riskification, and hedging","why":"The slide and Kuik reading frame hedging as insurance under uncertainty."},{"q":"Why is hedging not the same as neutrality?","opts":["A hedger actively combines engagement and countervailing measures with multiple powers","A hedger avoids all contact with great powers","Neutrality always requires military alliances","Hedging means no economic policy"],"ans":0,"topic":"Strategic uncertainty, riskification, and hedging","why":"Hedging uses active, even opposite, policy tools."},{"q":"Which is NOT one of the slide’s three hedging elements?","opts":["Permanent exclusive alignment with one great power","Not taking sides","Adopting opposite/counteracting measures","Preserving gains and a fallback position"],"ans":0,"topic":"Strategic uncertainty, riskification, and hedging","why":"Exclusive alignment contradicts the hedging logic."},{"q":"What does the risk-management framing add to hedging?","opts":["It focuses on uncertain possible harms rather than a single known enemy or threat","It assumes all threats are certain","It treats economics as irrelevant","It requires formal neutrality law"],"ans":0,"topic":"Strategic uncertainty, riskification, and hedging","why":"The Kuik reading links hedging to risk and uncertainty."},{"q":"Why is pro-U.S. versus pro-China often a misleading binary?","opts":["States can cooperate with each power in different issue areas at the same time","All ASEAN states have identical foreign policy","Only the U.S. has economic influence","China has no security relevance"],"ans":0,"topic":"Why Southeast Asian states avoid binary alignment","why":"Issue-specific combinations are central to Southeast Asian hedging."},{"q":"Why are weaker Southeast Asian states especially interested in hedging?","opts":["They face asymmetric power and want benefits without losing autonomy","They can easily coerce both great powers","They have no economic links to China","They control the global military balance"],"ans":0,"topic":"Strategic uncertainty, riskification, and hedging","why":"Small/middle states manage stronger partners by diversifying options."},{"q":"Can a state hedge differently across economic and security issues?","opts":["Yes; hedging portfolios can vary by issue and perceived risk","No; one alliance choice determines every policy","No; economic and security policy must always match","Only ASEAN as a whole can hedge"],"ans":0,"topic":"Why Southeast Asian states avoid binary alignment","why":"The course warns against binary country labels."},{"q":"What is strategic uncertainty?","opts":["Uncertainty about future power, intentions, commitment and regional outcomes","A legal ban on alliances","A fixed prediction that one power will dominate","Only uncertainty about exchange rates"],"ans":0,"topic":"Strategic uncertainty, riskification, and hedging","why":"Hedging exists because states cannot know future great-power behavior with confidence."},{"q":"What is the best metaphor for hedging in this course?","opts":["A portfolio of partially counteracting relationships and policies","A single all-or-nothing bet","A closed border","A fixed constitutional rule"],"ans":0,"topic":"Strategic uncertainty, riskification, and hedging","why":"The strategy diversifies gains and risks across options."}],"tu3-tools":[{"q":"What is economic pragmatism?","opts":["Maximizing economic gains through cooperation without requiring full strategic alignment","Ending trade with all great powers","Joining a military alliance automatically","Replacing markets with sanctions"],"ans":0,"topic":"Strategic uncertainty, riskification, and hedging","why":"It is the engagement/economic benefit side of hedging."},{"q":"What is indirect or soft balancing?","opts":["Building defense ties/capabilities without explicitly targeting a specific power","Signing unconditional surrender","Only increasing imports","Refusing all military cooperation"],"ans":0,"topic":"Strategic uncertainty, riskification, and hedging","why":"The slide defines it as military alignment/armament without direct explicit targeting."},{"q":"What is dominance denial?","opts":["Cultivating ties with multiple actors to reduce the risk of subservience to one power","Giving one power exclusive access","Ending diplomatic relations with all powers","Accepting a regional hegemon"],"ans":0,"topic":"Strategic uncertainty, riskification, and hedging","why":"Diversification prevents a single actor from dominating."},{"q":"What is binding engagement?","opts":["Enmeshing external powers in ASEAN-led bilateral and multilateral institutions","Excluding all major powers from ASEAN meetings","Creating one ASEAN army","Signing a secret alliance"],"ans":0,"topic":"Strategic uncertainty, riskification, and hedging","why":"Binding engagement tries to socialize and constrain powers through institutions."},{"q":"What is limited bandwagoning?","opts":["Selective foreign-policy cooperation with one power without becoming its security client","Full permanent subordination to one power","Refusal to cooperate with any power","Only economic sanctions"],"ans":0,"topic":"Strategic uncertainty, riskification, and hedging","why":"The key is collaboration without total alignment."},{"q":"What does ASEAN centrality mean most accurately here?","opts":["ASEAN provides a key institutional platform around which regional cooperation is organized","ASEAN commands the militaries of great powers","ASEAN is the strongest military power in Asia","ASEAN can veto every U.S.–China decision"],"ans":0,"topic":"Why Southeast Asian states avoid binary alignment","why":"Centrality is institutional/convening rather than dominance."},{"q":"What is ASEAN’s 'thickening effect'?","opts":["Dense meetings, forums and networks that create repeated interaction and practical cooperation","A single binding constitution","Military expansion","Closing regional borders"],"ans":0,"topic":"Why Southeast Asian states avoid binary alignment","why":"The slide highlights thousands of formal and informal interactions."},{"q":"Which principle belongs to the ASEAN Way?","opts":["Consensus and non-interference","Majority voting with compulsory sanctions","Supranational court supremacy","Automatic military intervention"],"ans":0,"topic":"Why Southeast Asian states avoid binary alignment","why":"Informality, consultation, consensus, non-interference and peaceful settlement are central."},{"q":"What does TAC refer to in the lecture?","opts":["Treaty of Amity and Cooperation, embodying ASEAN norms such as non-interference and peaceful settlement","Trans-Asian Currency Agreement","Trade Alliance Council","Treaty for Automatic Collective defense"],"ans":0,"topic":"Why Southeast Asian states avoid binary alignment","why":"The 1976 TAC is presented as an institutional expression of ASEAN norms."},{"q":"How can ASEAN have structural power despite member states being relatively small?","opts":["Its institutions have become embedded in regional architecture, so new initiatives often must adapt to them","It controls global finance","It has nuclear superiority","It annexes neighboring states"],"ans":0,"topic":"Why Southeast Asian states avoid binary alignment","why":"The slide argues institutional architecture itself becomes difficult to bypass."}],"tu3-limits":[{"q":"What problem arises from ASEAN’s state-centric focus?","opts":["It can miss subnational and transnational problems such as rights abuses and humanitarian crises","It gives civil society too much binding authority","It abolishes sovereignty","It prevents interstate diplomacy"],"ans":0,"topic":"Why Southeast Asian states avoid binary alignment","why":"The slide says state-to-state relations leave important problems under-addressed."},{"q":"What is a major downside of non-interference?","opts":["It restricts collective pressure on members over internal political or humanitarian crises","It forces ASEAN into every domestic dispute","It creates supranational government","It makes all decisions legally binding"],"ans":0,"topic":"Why Southeast Asian states avoid binary alignment","why":"The lecture cites disagreement and weak crisis responses."},{"q":"How can consensus constrain ASEAN?","opts":["A small number of dissenting members can prevent strong common action","It lets a majority impose any rule immediately","It gives the Secretariat unilateral power","It eliminates member preferences"],"ans":0,"topic":"Why Southeast Asian states avoid binary alignment","why":"Consensus supports cohesion but can produce lowest-common-denominator outcomes."},{"q":"What does weak implementation of the Five-Point Consensus illustrate?","opts":["ASEAN can agree politically but struggle to enforce member compliance","ASEAN has automatic coercive enforcement","Consensus always produces implementation","Non-interference has disappeared"],"ans":0,"topic":"Why Southeast Asian states avoid binary alignment","why":"The slide mentions inconsistent practice by member countries."},{"q":"What is a limitation of informal, non-binding negotiation?","opts":["Agreements may be easier to reach but harder to enforce","It always creates legal sanctions","It removes the need for trust","It makes unilateral policy impossible"],"ans":0,"topic":"Why Southeast Asian states avoid binary alignment","why":"The lecture directly links informality/non-binding approaches to weak enforcement."},{"q":"Can ASEAN by itself broker the fundamental U.S.–China great-power bargain?","opts":["Its mechanisms may ease tension but are too limited to determine the great-power bargain alone","Yes, ASEAN can order both powers to compromise","Yes, ASEAN controls their militaries","No, because ASEAN has no regional institutions"],"ans":0,"topic":"Why Southeast Asian states avoid binary alignment","why":"The slide explicitly distinguishes easing tension from brokering the deeper order."},{"q":"What does the lecture mean by socialization through ASEAN norms?","opts":["Repeated participation can encourage actors to become familiar with and partly adapt to regional expectations","ASEAN forces immediate identity change","Socialization means military recruitment","It guarantees all states become democracies"],"ans":0,"topic":"Why Southeast Asian states avoid binary alignment","why":"Norm congruence and repeated institutional contact are part of ASEAN’s order-building story."},{"q":"What criticism is made about ASEAN’s socialization effect on China?","opts":["Weak/non-binding norms can let China participate without substantial norm change","ASEAN has fully transformed Chinese domestic politics","China cannot join any ASEAN mechanism","TAC automatically solves all disputes"],"ans":0,"topic":"Why Southeast Asian states avoid binary alignment","why":"The lecture says the ASEAN Way may weaken socialization effects."},{"q":"Why is ASEAN unity difficult under great-power competition?","opts":["Members have different regimes, interests, dependencies and threat perceptions","All members share identical foreign policies","ASEAN requires one national government","Great powers have no economic ties in the region"],"ans":0,"topic":"Why Southeast Asian states avoid binary alignment","why":"Diverse domestic and external positions make common strategy difficult."},{"q":"What is the 'comfortable regionalism' criticism?","opts":["ASEAN may manage surface tensions without building a sufficiently strong regional order","ASEAN is too militarily aggressive","ASEAN has become a federal state","Regionalism has completely disappeared"],"ans":0,"topic":"Why Southeast Asian states avoid binary alignment","why":"The slide warns ASEAN can become mainly a convenient balancing arena."}]},"mastery":{"tu3-order":[{"q":"Why does fluctuating U.S. engagement create strategic uncertainty for Southeast Asia?","opts":["States value U.S. security presence but cannot assume the level of commitment will always be constant","It guarantees China will withdraw","It removes the need for regional institutions","It makes economic ties irrelevant"],"ans":0,"topic":"ASEAN between the United States and China","why":"Uncertain commitment creates incentives to diversify and hedge."},{"q":"Why can economic growth become a security concern to other states?","opts":["Greater wealth can finance technology, military capabilities and broader political influence","Economic growth always reduces military capacity","Security only depends on ideology","Trade prevents all power shifts"],"ans":0,"topic":"ASEAN between the United States and China","why":"Capabilities can convert economic resources into strategic power."},{"q":"What does the persistence of Korea/Taiwan show about the post-Cold War order?","opts":["The end of global bloc confrontation did not erase all regional security conflicts","The Cold War never ended anywhere","Economic globalization prevents territorial tension","Only domestic politics matters in East Asia"],"ans":0,"topic":"ASEAN between the United States and China","why":"Regional legacies can survive a systemic transition."},{"q":"Why does the lecture still call most East Asian institutions state-centric?","opts":["Governments remain the main decision-makers and integration is less supranational than the EU","They exclude all states","They have a single regional army","They directly elect one East Asian government"],"ans":0,"topic":"ASEAN between the United States and China","why":"Regional cooperation exists without EU-style supranational authority."},{"q":"Why is a power vacuum especially relevant to hedging?","opts":["When no external guarantor is fully reliable, states preserve multiple relationships and fallback options","It makes all alliances unnecessary","It forces every state to bandwagon with one power","It ends economic cooperation"],"ans":0,"topic":"ASEAN between the United States and China","why":"Uncertainty about leadership increases risk-management behavior."},{"q":"Why add strategic partnerships to hub-and-spoke alliances?","opts":["They broaden cooperation beyond formal treaty allies and adapt to a more complex region","They abolish existing alliances","They eliminate U.S. involvement","They are only cultural exchanges"],"ans":0,"topic":"ASEAN between the United States and China","why":"Partnerships complement rather than necessarily replace alliances."},{"q":"Which combination best captures the Pivot’s multi-dimensional character?","opts":["Military rebalancing plus TPP/economic engagement and participation in ASEAN-led forums","Only troop deployment with no diplomacy","Only cultural exchange","Only sanctions on allies"],"ans":0,"topic":"ASEAN between the United States and China","why":"The slide presents military, economic and political pillars."},{"q":"Why did FOIP signal stronger strategic competition with China?","opts":["It framed regional order around limiting China’s gains and strengthening balancing networks","It accepted Chinese regional dominance","It focused only on climate policy","It eliminated security partnerships"],"ans":0,"topic":"ASEAN between the United States and China","why":"FOIP became part of a more explicit competitive regional strategy."},{"q":"What is a major change in emphasis under Biden compared with Trump?","opts":["Stronger return to alliances, multilateral institutions and liberal democratic norms","Complete end of strategic competition","Rejection of ASEAN engagement","No willingness to cooperate on shared issues"],"ans":0,"topic":"ASEAN between the United States and China","why":"Biden combines competition with renewed multilateralism and alliance reassurance."},{"q":"Why are GDI/GSI/GCI strategically important beyond their stated policy fields?","opts":["They also offer Chinese frameworks and norms that can expand Beijing’s influence in global governance","They are purely domestic Chinese agencies","They have no connection to foreign policy","They replace all economic relations with military blocs"],"ans":0,"topic":"ASEAN between the United States and China","why":"Initiatives compete partly over ideas, institutions and legitimacy."}],"tu3-hedging":[{"q":"Why do these three fears point toward hedging rather than pure balancing or bandwagoning?","opts":["They require avoiding both overdependence on China and overreliance on an uncertain U.S. commitment","They all require choosing China exclusively","They all require rejecting both powers completely","They make regional institutions unnecessary"],"ans":0,"topic":"Why Southeast Asian states avoid binary alignment","why":"Hedging preserves multiple options against different possible risks."},{"q":"A government cannot confidently predict whether China will be benign or coercive in ten years. Which logic best supports hedging?","opts":["Uncertainty makes it rational to prepare for multiple futures rather than bet everything on one expectation","Uncertainty means policy should never change","Only complete alignment can reduce uncertainty","Economic ties reveal future intentions perfectly"],"ans":0,"topic":"Strategic uncertainty, riskification, and hedging","why":"Hedging is designed for uncertain future outcomes and intentions."},{"q":"A state expands trade with China while hosting more exercises with the U.S. What does this show?","opts":["Hedging can deliberately combine policies that point in different strategic directions","The state has no strategy","The state is fully bandwagoning with China","The state has ended all U.S. ties"],"ans":0,"topic":"Strategic uncertainty, riskification, and hedging","why":"Counteracting moves are a defining feature of hedging."},{"q":"Why does a fallback position matter?","opts":["It gives a state an alternative if its preferred relationship or expected future turns unfavorable","It guarantees no crisis can occur","It eliminates the need for diplomacy","It means choosing one power secretly"],"ans":0,"topic":"Strategic uncertainty, riskification, and hedging","why":"Insurance requires an alternative when one option fails."},{"q":"Why might a state hedge even if it does not currently see China or the U.S. as an enemy?","opts":["Hedging prepares for uncertain future behavior without requiring a present fixed threat judgment","Hedging only applies during declared war","Risk management requires identifying one enemy","States cannot insure against uncertainty"],"ans":0,"topic":"Strategic uncertainty, riskification, and hedging","why":"Risk can be managed before it becomes a definite threat."},{"q":"A state buys Chinese infrastructure, U.S. weapons and joins ASEAN mechanisms. How should it be classified?","opts":["As pursuing a diversified/hedging portfolio rather than a simple binary alignment","Automatically pro-China","Automatically pro-U.S.","Completely isolated"],"ans":0,"topic":"Why Southeast Asian states avoid binary alignment","why":"Different relationships serve different goals and reduce dependence."},{"q":"What is the core autonomy problem under asymmetry?","opts":["Dependence on one much stronger partner can create vulnerability to pressure or subservience","Smaller states always dominate stronger ones","Asymmetry guarantees equal bargaining power","Economic benefits eliminate political leverage"],"ans":0,"topic":"Strategic uncertainty, riskification, and hedging","why":"Hedging helps reduce the political risks of asymmetric dependence."},{"q":"Why is issue-specific variation analytically useful?","opts":["It explains why apparently contradictory policies can still form a coherent risk-management strategy","It proves states lack preferences","It means domestic politics never matters","It makes all foreign policies identical"],"ans":0,"topic":"Why Southeast Asian states avoid binary alignment","why":"Different tools can insure different risks."},{"q":"If future intentions became perfectly known and benign, what would happen to the logic for hedging?","opts":["The insurance value of counteracting measures would decline because uncertainty is lower","Hedging would automatically intensify","All economic ties would end","ASEAN would cease to exist"],"ans":0,"topic":"Strategic uncertainty, riskification, and hedging","why":"Hedging’s rationale grows with uncertainty and downside risk."},{"q":"Why is a portfolio analogy better than 'sitting on the fence'?","opts":["A portfolio requires active allocation across options to manage exposure, not passive indecision","Both mean doing nothing","A portfolio always chooses one asset","Foreign policy cannot diversify"],"ans":0,"topic":"Strategic uncertainty, riskification, and hedging","why":"Hedging is purposeful risk diversification."}],"tu3-tools":[{"q":"A state welcomes Chinese investment while criticizing China on a security issue. Which hedging behavior explains the investment choice?","opts":["Economic pragmatism","Full bandwagoning","Autarky","Direct balancing"],"ans":0,"topic":"Strategic uncertainty, riskification, and hedging","why":"Economic cooperation can be pursued separately from security alignment."},{"q":"A country increases naval exercises with several partners but publicly says the moves target no state. Which tool is this?","opts":["Indirect/soft balancing","Economic pragmatism","Limited bandwagoning with China","Complete neutrality"],"ans":0,"topic":"Strategic uncertainty, riskification, and hedging","why":"It adds counterweight without an overt anti-power alliance."},{"q":"Why can welcoming Japan, India, Europe and the U.S. alongside China support dominance denial?","opts":["More partners reduce any one power’s leverage and preserve alternatives","More partners always create one dominant patron","It forces ASEAN to abandon China","It eliminates economic interdependence"],"ans":0,"topic":"Strategic uncertainty, riskification, and hedging","why":"External diversification reduces concentration risk."},{"q":"Why invite competing powers into the same ASEAN-led forums?","opts":["Regular interaction can embed them in shared procedures and make ASEAN a central convening platform","It guarantees they surrender sovereignty","It ends strategic competition permanently","It makes consensus unnecessary"],"ans":0,"topic":"Strategic uncertainty, riskification, and hedging","why":"Institutional enmeshment is a form of risk management and regional order-building."},{"q":"Why is 'limited' crucial in limited bandwagoning?","opts":["The state gains from selective alignment while keeping autonomy and other relationships","It means the cooperation has no strategic effect","It requires ending all other partnerships","It is identical to full alliance dependence"],"ans":0,"topic":"Strategic uncertainty, riskification, and hedging","why":"The limit preserves room to maneuver."},{"q":"Why might great powers accept ASEAN-led meetings despite ASEAN members being weaker?","opts":["ASEAN is relatively non-threatening and offers an established, broadly acceptable platform","ASEAN can militarily compel attendance","Great powers have no bilateral channels","ASEAN has supranational legal authority over them"],"ans":0,"topic":"Why Southeast Asian states avoid binary alignment","why":"Weakness can become convening leverage when neutrality/acceptability matters."},{"q":"Why can repeated low-level meetings matter even without binding enforcement?","opts":["They build networks, habits, information exchange and channels for problem-solving","They automatically solve every dispute","They remove national interests","They make diplomacy unnecessary"],"ans":0,"topic":"Why Southeast Asian states avoid binary alignment","why":"Institutional density can socialize actors and lower transaction costs."},{"q":"Why can the ASEAN Way be both a strength and a weakness?","opts":["It makes cooperation acceptable to diverse states but can slow action and weaken enforcement","It is strong because it eliminates sovereignty","It is weak because ASEAN never meets","It has no relevance to political trust"],"ans":0,"topic":"Why Southeast Asian states avoid binary alignment","why":"Low-coercion rules support inclusion but reduce decisiveness."},{"q":"Why was China’s accession to TAC significant in the professor’s argument?","opts":["It showed an external great power accepting ASEAN’s normative framework, encouraging wider participation","It made China an ASEAN member","It created a unified ASEAN-China military","It abolished the South China Sea disputes"],"ans":0,"topic":"Why Southeast Asian states avoid binary alignment","why":"Norm adoption supports ASEAN’s socialization/centrality claim."},{"q":"What makes institutional path dependence a form of leverage?","opts":["Once many actors organize cooperation around ASEAN mechanisms, replacing them becomes costly and politically difficult","Institutions physically prevent new organizations","Path dependence guarantees legal supremacy","It eliminates great-power interests"],"ans":0,"topic":"Why Southeast Asian states avoid binary alignment","why":"Established architecture shapes the options available to later actors."}],"tu3-limits":[{"q":"Why are Rohingya-type crises hard for a strictly state-centric regionalism?","opts":["The harm crosses borders and involves internal state conduct that non-interference makes difficult to address","They are purely trade disputes","They require no regional cooperation","They are solved automatically by consensus"],"ans":0,"topic":"Why Southeast Asian states avoid binary alignment","why":"Humanitarian/rights issues challenge sovereignty-centered mechanisms."},{"q":"Why can non-interference preserve unity in normal times yet weaken crisis response?","opts":["Members feel safer joining cooperation, but the same restraint limits intervention when domestic actions create regional harm","The principle only concerns tariffs","It requires unanimous military action","It makes domestic crises impossible"],"ans":0,"topic":"Why Southeast Asian states avoid binary alignment","why":"Sovereignty protection trades off against collective action."},{"q":"Why can great-power rivalry worsen the consensus problem?","opts":["Members have different external dependencies and threat perceptions, making a common position harder","All members have identical China/U.S. ties","Rivalry removes national interests","External powers cannot influence ASEAN members"],"ans":0,"topic":"Why Southeast Asian states avoid binary alignment","why":"Different alignments can fragment ASEAN unity."},{"q":"What institutional gap is exposed when agreed principles are not implemented?","opts":["A gap between norm-setting and enforcement capability","A lack of any meetings","A shortage of trade data","Too much supranational authority"],"ans":0,"topic":"Why Southeast Asian states avoid binary alignment","why":"ASEAN can generate norms without strong coercive mechanisms."},{"q":"Why might actors still prefer informal rules?","opts":["They lower sovereignty costs and make participation politically easier","They are always more coercive","They guarantee compliance","They eliminate ambiguity"],"ans":0,"topic":"Why Southeast Asian states avoid binary alignment","why":"Flexibility is attractive even though it reduces enforceability."},{"q":"What is the strongest realistic claim for ASEAN under rivalry?","opts":["It can provide forums, norms and buffers that manage competition without controlling its ultimate outcome","It can end great-power competition permanently","It is irrelevant to regional order","It must choose one hegemon"],"ans":0,"topic":"Why Southeast Asian states avoid binary alignment","why":"Centrality is meaningful but bounded."},{"q":"Why can weak enforcement still produce some influence?","opts":["Actors may adjust behavior over time through repeated interaction, reputation and accepted procedures","Only legal punishment can influence states","Norms have no effect without a world government","Meetings prevent all self-interest"],"ans":0,"topic":"Why Southeast Asian states avoid binary alignment","why":"Institutional influence can be social/reputational as well as coercive."},{"q":"Why is participation not the same as internalization?","opts":["A state can attend institutions and use their benefits without deeply changing preferences or behavior","Attendance legally changes national interests","Participation guarantees compliance forever","Internalization only concerns trade"],"ans":0,"topic":"Why Southeast Asian states avoid binary alignment","why":"Institutional membership varies in depth."},{"q":"How can one member’s close dependence on a great power affect the whole organization?","opts":["It can weaken consensus on actions that would impose costs on that power","It automatically strengthens coercive unity","It gives ASEAN supranational authority","It has no institutional effect"],"ans":0,"topic":"Why Southeast Asian states avoid binary alignment","why":"Consensus makes individual external alignments regionally consequential."},{"q":"What distinguishes order management from order-building?","opts":["Management contains day-to-day friction; order-building creates stronger rules/capacity to shape deeper behavior","They are identical","Order-building requires no institutions","Management always means military intervention"],"ans":0,"topic":"Why Southeast Asian states avoid binary alignment","why":"ASEAN may be better at keeping channels open than enforcing a deep settlement."}]},"cumulativeId":"tu3-all","flashcards":{"id":"tu101-l3","label":"Lecture 3 • ASEAN Between Giants: U.S., China, and the New Global Cold War","description":"U.S.–China competition, strategic uncertainty, hedging, ASEAN centrality and its limits.","cumulativeId":"tu101-l3-full-v1","cumulativeLabel":"Full Lecture • Lecture 3","parts":[{"id":"tu3-l3-order-v1","label":"Part 1 • Post-Cold War Order & Great-Power Competition","description":"Regional structure, China’s rise and changing U.S. strategy.","cards":[{"id":"us-guarantor","front":"What role did the U.S. retain in post-Cold War East Asia?","back":"A major security guarantor whose engagement still fluctuated ไทยช่วยจำ: สหรัฐฯ ยังสำคัญด้านความมั่นคง แต่ระดับการมีส่วนร่วมไม่คงที่"},{"id":"china-rise","front":"What does the lecture include in the 'rise of China' beyond GDP growth?","back":"Technological upgrading, military modernization and proactive foreign policy ไทยช่วยจำ: เศรษฐกิจโตสามารถแปลงเป็นเทคโนโลยี ทหาร และอิทธิพล"},{"id":"cw-tensions","front":"Which unresolved tensions remain from the Cold War environment?","back":"The Korean Peninsula and Taiwan issue ไทยช่วยจำ: สงครามเย็นจบแต่ปัญหาภูมิภาคบางเรื่องยังค้าง"},{"id":"institutions","front":"Which institutions illustrate expanding East Asian regionalism?","back":"ASEAN, APEC, AFTA, ARF, ASEAN+3 and East Asia Summit ไทยช่วยจำ: มีสถาบันเยอะ แต่รัฐยังเป็นศูนย์กลาง"},{"id":"power-vacuum","front":"What concern followed reduced U.S. presence after the Vietnam War?","back":"A perceived power vacuum and uncertainty about Japan and China ไทยช่วยจำ: ช่องว่างอำนาจทำให้รัฐกระจายความสัมพันธ์"},{"id":"hub-spoke","front":"What is the hub-and-spoke system?","back":"U.S.-centered bilateral alliances linking Washington separately with regional allies ไทยช่วยจำ: hub-and-spoke = สหรัฐฯ เป็นศูนย์กลางเชื่อมพันธมิตรแต่ละประเทศ"},{"id":"obama","front":"What was a core purpose of Obama’s Pivot to Asia?","back":"Reprioritize Asia-Pacific, manage China’s rise and reassure allies ไทยช่วยจำ: Pivot = ทหาร + เศรษฐกิจ + การทูต"},{"id":"trump","front":"What distinguished Trump’s Asia approach in the lecture?","back":"America First, transactional diplomacy and promotion of the Free and Open Indo-Pacific ไทยช่วยจำ: FOIP สะท้อนการแข่งขันกับจีนชัดขึ้น"},{"id":"biden","front":"What is a major continuity under Biden?","back":"China remains a strategic competitor ไทยช่วยจำ: จีนยังเป็นคู่แข่ง แต่ Biden เน้นพันธมิตรและ multilateralism มากขึ้น"},{"id":"gdi-gsi-gci","front":"Which trio represents China’s newer global initiatives?","back":"GDI, GSI and GCI ไทยช่วยจำ: จีนแข่งขันผ่านกรอบการพัฒนา ความมั่นคง และอารยธรรมด้วย"}]},{"id":"tu3-l3-hedging-v1","label":"Part 2 • Strategic Uncertainty & Hedging","description":"Why binary alignment is unattractive and how hedging manages risk.","cards":[{"id":"three-risks","front":"Which three outcomes does Southeast Asia seek to prevent in the slide?","back":"China’s domination, U.S. withdrawal and unstable regional order ไทยช่วยจำ: กัน 3 อย่าง: จีนครอบงำ สหรัฐฯ ถอน ระเบียบวุ่น"},{"id":"hedge-def","front":"What is hedging in this lecture?","back":"Risk-management behavior that preserves options under strategic uncertainty ไทยช่วยจำ: hedging = ประกันความเสี่ยงเมื่ออนาคตไม่แน่นอน"},{"id":"not-neutral","front":"Why is hedging not the same as neutrality?","back":"A hedger actively combines engagement and countervailing measures with multiple powers ไทยช่วยจำ: hedging ไม่ใช่อยู่เฉย แต่ทำหลายทางพร้อมกัน"},{"id":"three-elements","front":"Which is NOT one of the slide’s three hedging elements?","back":"Permanent exclusive alignment with one great power ไทยช่วยจำ: fallback = ทางสำรองถ้าความสัมพันธ์หลักไม่เป็นไปตามคาด"},{"id":"riskification","front":"What does the risk-management framing add to hedging?","back":"It focuses on uncertain possible harms rather than a single known enemy or threat ไทยช่วยจำ: risk ≠ threat ที่แน่นอน จึง hedging ได้แม้ยังไม่มองใครเป็นศัตรู"},{"id":"binary","front":"Why is pro-U.S. versus pro-China often a misleading binary?","back":"States can cooperate with each power in different issue areas at the same time ไทยช่วยจำ: แต่ละ issue เลือกความสัมพันธ์ต่างกันได้"},{"id":"asymmetry","front":"Why are weaker Southeast Asian states especially interested in hedging?","back":"They face asymmetric power and want benefits without losing autonomy ไทยช่วยจำ: รัฐเล็กกังวลพึ่งมหาอำนาจมากเกินจนเสีย autonomy"},{"id":"issue-specific","front":"Can a state hedge differently across economic and security issues?","back":"Yes; hedging portfolios can vary by issue and perceived risk ไทยช่วยจำ: ต่าง issue ใช้กลยุทธ์ต่างได้แต่รวมเป็นพอร์ตเดียว"},{"id":"uncertainty","front":"What is strategic uncertainty?","back":"Uncertainty about future power, intentions, commitment and regional outcomes ไทยช่วยจำ: ยิ่งอนาคตไม่แน่นอน ยิ่งมีเหตุผลทำ hedging"},{"id":"portfolio","front":"What is the best metaphor for hedging in this course?","back":"A portfolio of partially counteracting relationships and policies ไทยช่วยจำ: hedging = กระจายพอร์ตความสัมพันธ์ ไม่ใช่ลังเลเฉย ๆ"}]},{"id":"tu3-l3-tools-v1","label":"Part 3 • Hedging Tools & ASEAN Centrality","description":"Five hedging behaviors and why ASEAN can convene great powers.","cards":[{"id":"econ-prag","front":"What is economic pragmatism?","back":"Maximizing economic gains through cooperation without requiring full strategic alignment ไทยช่วยจำ: ร่วมมือเศรษฐกิจเพื่อผลประโยชน์ โดยไม่ต้องเลือกข้างทั้งหมด"},{"id":"soft-balance","front":"What is indirect or soft balancing?","back":"Building defense ties/capabilities without explicitly targeting a specific power ไทยช่วยจำ: เสริมความมั่นคงแบบไม่ประกาศว่าต่อต้านใคร"},{"id":"dominance-denial","front":"What is dominance denial?","back":"Cultivating ties with multiple actors to reduce the risk of subservience to one power ไทยช่วยจำ: หลาย partner ช่วยไม่ให้ใครผูกขาดอิทธิพล"},{"id":"binding","front":"What is binding engagement?","back":"Enmeshing external powers in ASEAN-led bilateral and multilateral institutions ไทยช่วยจำ: ดึงมหาอำนาจเข้ากรอบ ASEAN เพื่อผูกไว้กับกติกา/การพบปะ"},{"id":"limited-band","front":"What is limited bandwagoning?","back":"Selective foreign-policy cooperation with one power without becoming its security client ไทยช่วยจำ: ร่วมบางเรื่อง แต่ยังรักษา autonomy/partner อื่น"},{"id":"centrality","front":"What does ASEAN centrality mean most accurately here?","back":"ASEAN provides a key institutional platform around which regional cooperation is organized ไทยช่วยจำ: centrality = เวทีกลาง/สถาปัตยกรรม ไม่ใช่อำนาจทหารเหนือมหาอำนาจ"},{"id":"thickening","front":"What is ASEAN’s 'thickening effect'?","back":"Dense meetings, forums and networks that create repeated interaction and practical cooperation ไทยช่วยจำ: ประชุม/เครือข่ายถี่ ๆ สร้างนิสัยร่วมมือและช่องทางแก้ปัญหา"},{"id":"asean-way","front":"Which principle belongs to the ASEAN Way?","back":"Consensus and non-interference ไทยช่วยจำ: ยอมรับง่ายเพราะเคารพอธิปไตย แต่ตัดสินใจ/บังคับใช้ช้า"},{"id":"tac","front":"What does TAC refer to in the lecture?","back":"Treaty of Amity and Cooperation, embodying ASEAN norms such as non-interference and peaceful settlement ไทยช่วยจำ: TAC = กติกาความสัมพันธ์แบบ ASEAN ที่มหาอำนาจเข้าร่วมได้"},{"id":"structural-power","front":"How can ASEAN have structural power despite member states being relatively small?","back":"Its institutions have become embedded in regional architecture, so new initiatives often must adapt to them ไทยช่วยจำ: สถาบันที่ฝังตัวแล้วทำให้คนอื่นต้องปรับตัวเข้าหา"}]},{"id":"tu3-l3-limits-v1","label":"Part 4 • ASEAN Limits & Regional Order","description":"Non-interference, weak enforcement, internal division and the limits of centrality.","cards":[{"id":"state-centric","front":"What problem arises from ASEAN’s state-centric focus?","back":"It can miss subnational and transnational problems such as rights abuses and humanitarian crises ไทยช่วยจำ: ปัญหาข้ามชาติ/ภายในรัฐแก้ยากถ้า ASEAN มองแต่รัฐต่อรัฐ"},{"id":"noninterference","front":"What is a major downside of non-interference?","back":"It restricts collective pressure on members over internal political or humanitarian crises ไทยช่วยจำ: ช่วยให้รัฐสบายใจร่วม ASEAN แต่จำกัดการกดดันเมื่อเกิดวิกฤต"},{"id":"consensus","front":"How can consensus constrain ASEAN?","back":"A small number of dissenting members can prevent strong common action ไทยช่วยจำ: สมาชิกพึ่งพามหาอำนาจต่างกัน จึงหาฉันทามติยาก"},{"id":"five-point","front":"What does weak implementation of the Five-Point Consensus illustrate?","back":"ASEAN can agree politically but struggle to enforce member compliance ไทยช่วยจำ: ตกลงได้ แต่บังคับให้ทำตามยาก"},{"id":"informal","front":"What is a limitation of informal, non-binding negotiation?","back":"Agreements may be easier to reach but harder to enforce ไทยช่วยจำ: ยืดหยุ่นจึงเข้าร่วมง่าย แต่บังคับใช้ต่ำ"},{"id":"broker","front":"Can ASEAN by itself broker the fundamental U.S.–China great-power bargain?","back":"Its mechanisms may ease tension but are too limited to determine the great-power bargain alone ไทยช่วยจำ: ASEAN ช่วย manage ความตึงเครียด แต่กำหนดดีลมหาอำนาจไม่ได้เอง"},{"id":"socialization","front":"What does the lecture mean by socialization through ASEAN norms?","back":"Repeated participation can encourage actors to become familiar with and partly adapt to regional expectations ไทยช่วยจำ: การพบปะซ้ำ ๆ ทำให้คุ้นและบางครั้งปรับตัวตามบรรทัดฐาน"},{"id":"china-norm","front":"What criticism is made about ASEAN’s socialization effect on China?","back":"Weak/non-binding norms can let China participate without substantial norm change ไทยช่วยจำ: เข้าร่วมเวที ≠ ยอมรับบรรทัดฐานอย่างลึกซึ้งเสมอ"},{"id":"unity","front":"Why is ASEAN unity difficult under great-power competition?","back":"Members have different regimes, interests, dependencies and threat perceptions ไทยช่วยจำ: ผลประโยชน์/การพึ่งพาต่างกันกระทบฉันทามติทั้งกลุ่ม"},{"id":"comfortable","front":"What is the 'comfortable regionalism' criticism?","back":"ASEAN may manage surface tensions without building a sufficiently strong regional order ไทยช่วยจำ: ลดแรงเสียดทานได้ แต่ยังไม่สร้างระเบียบที่แข็งพอ"}]}]}};window.dispatchEvent(new CustomEvent("d-study-tu101-module-loaded",{detail:{id:"l3"}}));})();